import re,glob,collections
cases=[];bad=[]
for f in sorted(glob.glob('*.txt')):
    t=open(f).read()
    pages=re.split(r'=== page \d+\n',t)[1:]
    for i,p in enumerate(pages):
        if 'finds the following' not in p: 
            if 'Case Number' in p: bad.append((f,i,'nofind'))
            continue
        m=re.search(r'finds the following\s+violation\(s\):\s*(.*?)\s*The Advisory Committee recommends[^\n]*\n(.*?)(Abstentions|$)',p,re.S)
        if not m: bad.append((f,i,'nomatch'));continue
        cases.append((f,m.group(1).strip(),m.group(2).strip()))
print(len(cases),bad[:10],len(bad))
import pickle;pickle.dump(cases,open('/tmp/r2run-wrtvxw1q/data/../x.pkl','wb')) if False else None
c=collections.Counter()
for f,cite,rec in cases:
    if not re.fullmatch(r'IC 8-1-26-\d+(\([a-z0-9]\))*(\([a-z-]{2,}\))?',cite): print(repr(cite),f)
for f,cite,rec in cases:
    if not rec.startswith('$') and '$' in rec or '$' not in rec: c[rec[:60]]+=1
print(c.most_common(20))
E
